```js
/**
 * The interpreter that can `import uno`, or undefined.
 *
 * It ships with LibreOffice — the pyuno deb brings `program/python` and `uno.py`
 * next to the binary — so it is looked for beside whichever office is going to be
 * used: the cached tarball's, or (when a distro LibreOffice already answers on the
 * PATH) the sibling of the `soffice` that PATH resolves to. The PATH one is
 * probed, not assumed: a distro package can ship the office without a Python that
 * sees `uno`, and then the tarball is what has to be unpacked.
 */
export function unoInterpreter(sofficePath) { ... }
```

Simplest implementation:
```js
export function unoPython() {
  const cached = join(LO_PROGRAM, "python");
  if (existsSync(cached)) return cached;
  const which = spawnSync("sh", ["-c", "command -v soffice"], { encoding: "utf8" });
  ...
}
```
Hmm, avoid shell. Use `spawnSync("soffice", ...)` path resolution: we know PATH soffice answered `--version`; to get its path, we can use `spawnSync("sh", ["-c", "readlink -f \"$(command -v soffice)\""])`. That's a shell - but shell_guard only applies to my own tool calls, not to repo code. Still, cleaner: probe candidate interpreters in a fixed order:

1. `join(LO_PROGRAM, "python")` (the cache)
2. for each `bin` in ["soffice"] resolved via PATH... Node has no `which`. But we can just probe the *known distro locations* — no, fragile.

Better: use Node's own resolution by reading PATH entries:
```js
function onPath(name) {
  for (const dir of (process.env.PATH ?? "").split(":")) {
    const candidate = join(dir, name);
    if (existsSync(candidate)) return candidate;
  }
  return undefined;
}
```
That's small and dependency-free. Then:
```js
export function unoPython(sofficePath) {
  const probe = (interpreter) =>
    existsSync(interpreter) && spawnSync(interpreter, ["-c", "import uno"], { encoding: "utf8" }).status === 0;
  const cached = join(LO_PROGRAM, "python");
  const candidates = [cached];
  // a distro office keeps its interpreter beside its own binary
  const onPathSoffice = onPath("soffice");
  if (onPathSoffice) {
    const real = spawnSync("readlink", ["-f", onPathSoffice], { encoding: "utf8" }).stdout?.trim();
    if (real) candidates.push(join(dirname(real), "python"));
  }
  return candidates.find(probe);
}
```
And `libreOffice({ uno })`:
```js
export function libreOffice({ uno = false } = {}) {
  const onPath = spawnSync("soffice", ["--version"], { encoding: "utf8" });
